public int NetworkDelayTime(int[][] times, int n, int k) {
    var adj = new List<(int to, int w)>[n + 1];
    for (int v = 1; v <= n; v++) adj[v] = new List<(int, int)>();
    foreach (var t in times) adj[t[0]].Add((t[1], t[2]));
    var dist = new int[n + 1];
    Array.Fill(dist, int.MaxValue);
    dist[k] = 0;
    var pq = new PriorityQueue<int, int>();      // .NET 6+: node by distance
    pq.Enqueue(k, 0);
    while (pq.TryDequeue(out int u, out int d)) {
        if (d > dist[u]) continue;               // a stale entry
        foreach (var (v, w) in adj[u])
            if (d + w < dist[v]) {
                dist[v] = d + w;
                pq.Enqueue(v, dist[v]);          // no decrease-key: push again
            }
    }
    int max = 0;
    for (int v = 1; v <= n; v++) {
        if (dist[v] == int.MaxValue) return -1;  // the signal missed someone
        max = Math.Max(max, dist[v]);
    }
    return max;
}

