public int FindCheapestPrice(int n, int[][] flights, int src, int dst, int k) {
    var cost = new int[n];
    Array.Fill(cost, int.MaxValue);
    cost[src] = 0;
    for (int round = 0; round <= k; round++) {           // pass i: paths of ≤ i + 1 flights
        var next = (int[])cost.Clone();                  // read the last pass, write a copy
        foreach (var f in flights)
            if (cost[f[0]] != int.MaxValue && cost[f[0]] + f[2] < next[f[1]])
                next[f[1]] = cost[f[0]] + f[2];
        cost = next;
    }
    return cost[dst] == int.MaxValue ? -1 : cost[dst];
}

