// the fewest walls to break on the way s → t: entering an empty cell costs 0, a wall costs 1
int MinWalls(bool[] wall, int w, int h, int s, int t) {
    var dist = new int[w * h];
    Array.Fill(dist, int.MaxValue);
    dist[s] = 0;
    var deque = new LinkedList<int>();
    deque.AddFirst(s);
    while (deque.Count > 0) {
        int u = deque.First.Value;
        deque.RemoveFirst();
        int x = u % w;
        for (int k = 0; k < 4; k++) {
            int v = k == 0 ? (x > 0 ? u - 1 : -1) : k == 1 ? (x < w - 1 ? u + 1 : -1) : k == 2 ? u - w : u + w;
            if (v < 0 || v >= w * h) continue;
            int c = wall[v] ? 1 : 0;
            if (dist[u] + c >= dist[v]) continue;
            dist[v] = dist[u] + c;
            if (c == 0) deque.AddFirst(v); else deque.AddLast(v);   // 0 to the front, 1 to the back
        }
    }
    return dist[t];
}

