MinHeap<long> heap = new MinHeap<long>();   // the heap from the unit on heaps + Clear(): n = 0
int[] dist;

int[] Dijkstra(int[] cost, int w, int h, int start) {
    int size = w * h;
    if (dist == null || dist.Length != size) dist = new int[size];
    Array.Fill(dist, int.MaxValue);
    heap.Clear();
    dist[start] = 0;
    heap.Push(start);                                      // key (0 << 32) | start
    while (heap.Count > 0) {
        long top = heap.Pop();
        int u = (int)(top & 0xFFFFFFFF), d = (int)(top >> 32);
        if (d > dist[u]) continue;                         // lazy deletion
        int x = u % w;
        if (x > 0) Relax(cost, u - 1, d);
        if (x < w - 1) Relax(cost, u + 1, d);
        if (u >= w) Relax(cost, u - w, d);
        if (u + w < size) Relax(cost, u + w, d);
    }
    return dist;
}

void Relax(int[] cost, int v, int d) {
    if (cost[v] == 0) return;                             // 0 is a wall
    int nd = d + cost[v];                                 // the cost sits on the cell we enter
    if (nd >= dist[v]) return;
    dist[v] = nd;
    heap.Push(((long)nd << 32) | (uint)v);
}
